Object.assign(CONTENT.ar,{realSign:'لافتة EASYOIL الرسمية',realPhoto:'EASYOIL · صورة مقدمة من الشركة',logisticsLabel:'الخدمات اللوجستية والتوزيع',logisticsTitle:'الطاقة، أقرب<br>إلى الاحتياجات.',logisticsText:'من التخزين إلى التوزيع، تعتمد استمرارية الإمداد على المعدات المناسبة والتنسيق الدقيق. يربط نهجنا متطلبات المنتج والخدمات اللوجستية وظروف الاستلام لدى العميل.',logisticsAlt:'خزان ومعدات توزيع بألوان EASYOIL',logisticsSteps:['الإمداد والنقل','التخزين والتنسيق اللوجستي','التوزيع والتسليم'],imageDisclaimer:'صور EASYOIL وصور توضيحية للأسواق الدولية والغاز والطاقة المتجددة.'});
